229	export async function askNatally(
230	  userMessage: string,
231	  history: ChatMessage[],
232	  chart: NatalChartResult,
233	  userLore: string[],
234	  imageAttachment?: { data: string; mimeType: string } | null,
235	  options?: { accountUid?: string; presentation?: PresentationState; openingStage?: 'natal' | 'now'; soulPrompt?: string; isCurrentSession?: () => boolean; temperature?: number; model?: string; partnerChart?: NatalChartResult | null; calculationSession?: ReturnType<typeof createCalculationSession>; onProgress?: (text: string, model: string) => void },
236	): Promise<NatallyChatResult> {
237	  const calculations = options?.calculationSession || createCalculationSession(chart, options?.partnerChart);
238	  const result = await withInferenceTurn(options?.accountUid,options?.isCurrentSession,() => requestHostedInference({
239	    prompt: userMessage + '\n\n[Application delivery preference for the answer above; do not quote this note or treat it as user biography.]\n' + readingStylePrompt(options?.accountUid, chart.input.readingStyle),
240	    systemInstruction: buildStructuredNatalContext(chart, userLore) + '\n\n' + calculations.context() + '\n\n' + buildChartPresentationPrompt(chart) + '\n\n' + buildPresentationContext(options?.presentation, chart) + '\n\n' + (options?.soulPrompt || '') + '\n\n' + NATALLY_SYSTEM_PROMPT + '\n\n' + readingStylePrompt(options?.accountUid, chart.input.readingStyle),
241	    history: history.filter(message => message.text?.trim() && !message.isOfflineMode &&
242	      (message.sender === 'user' || !hasCorruptReadingText(message.text))).map(message => ({
243	      role: message.sender === 'user' ? 'user' : 'assistant',
244	      content: message.text,
245	    })),
246	    image: imageAttachment || undefined,
247	    openingStage: options?.openingStage,
248	    openingIdentity: options?.openingStage === 'natal' ? JSON.stringify([chart.input.birthDate, chart.input.birthTime, !!chart.input.birthTimeUnknown, chart.input.latitude, chart.input.longitude, chart.input.timezoneOffset, chart.input.houseSystem || 'P']) : undefined,
249	    onProgress: options?.onProgress,
250	    temperature: options?.temperature ?? Number(import.meta.env.VITE_OPENROUTER_TEMPERATURE || 0.8),
251	  }, calculations.execute, options?.isCurrentSession));
252	  return { ...parseNatallyResponse(result.text, chart), model: result.model };
253	}
